{
  "labels": [
    {
      "i": 0,
      "speaker": "bot",
      "text": "Hello आपको small size सुपारी cutting machine की requirement है ना?"
    },
    {
      "i": 1,
      "speaker": "caller",
      "text": "हाँ नमस्कार Madam मैं Pune से बात कर रहा हूँ।"
    },
    {
      "i": 2,
      "speaker": "bot",
      "text": "ठीक है मैं Taniya बोल रही हूं IndiaMART से।"
    },
    {
      "i": 3,
      "speaker": "bot",
      "text": "हमारे पास कई अच्छे sellers available हैं जिनसे मैं अभी आपको connect करवाऊंगी।"
    },
    {
      "i": 4,
      "speaker": "bot",
      "text": "बस कुछ details confirm कर दीजिए।"
    },
    {
      "i": 5,
      "speaker": "bot",
      "text": "चलिए आप cutting type के बारे में बताइए।"
    },
    {
      "i": 6,
      "speaker": "bot",
      "text": "आपको कौन सा चाहिए diamond cut, chips cut या कुछ और?"
    },
    {
      "i": 7,
      "speaker": "caller",
      "text": "Hello."
    },
    {
      "i": 8,
      "speaker": "caller",
      "text": "वो बारीक सुपारी जो है ना बारीक cut करने का है बारीक।"
    },
    {
      "i": 9,
      "speaker": "bot",
      "text": "कितने piece चाहिए?"
    },
    {
      "i": 10,
      "speaker": "bot",
      "text": "माफ़ कीजिए आपकी बात सुन"
    },
    {
      "i": 11,
      "speaker": "bot",
      "text": "समझ गई आपको छोटे-छोटे टुकड़ों में cutting चाहिए।"
    },
    {
      "i": 12,
      "speaker": "bot",
      "text": "अब capacity के बारे में बता दीजिए।"
    },
    {
      "i": 13,
      "speaker": "bot",
      "text": "बीस kg प्रति घंटा, पच्चीस kg प्रति घंटा या कुछ और?"
    },
    {
      "i": 14,
      "speaker": "caller",
      "text": "हाँ जी दस से पंद्रह पंद्रह kg प्रति घंटा।"
    },
    {
      "i": 15,
      "speaker": "bot",
      "text": "ठीक है आप अपनी city और state भी बता दीजिए please."
    },
    {
      "i": 16,
      "speaker": "caller",
      "text": "काहे को सुना?"
    },
    {
      "i": 17,
      "speaker": "bot",
      "text": "आप Pune Maharashtra से बोल रहे हैं ना?"
    },
    {
      "i": 18,
      "speaker": "caller",
      "text": "हाँ अपनी महाशय।"
    },
    {
      "i": 19,
      "speaker": "bot",
      "text": "बहुत बढ़िया।"
    },
    {
      "i": 20,
      "speaker": "bot",
      "text": "अब आप अपना नाम बता दीजिए please।"
    },
    {
      "i": 21,
      "speaker": "caller",
      "text": "माझं नाव आहे राजेश लिंबाजी समोणजी."
    },
    {
      "i": 22,
      "speaker": "bot",
      "text": "बहुत बढ़िया।"
    },
    {
      "i": 23,
      "speaker": "bot",
      "text": "आपको मैं seller details WhatsApp पे भेज दूंगी जिनसे आप details और price discuss कर सकते हैं।"
    },
    {
      "i": 24,
      "speaker": "bot",
      "text": "IndiaMART चुनने के लिए धन्यवाद।"
    },
    {
      "i": 25,
      "speaker": "bot",
      "text": "आपका दिन शुभ हो।"
    },
    {
      "i": 26,
      "speaker": "caller",
      "text": "ठीक।"
    }
  ]
}
